pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the callee selector byte and whether calldata is empty; we need a helper contract
    // to manifest different behavior between call(...) and call{value:0}(...).
    function testFuzz_property(bytes1 firstByte, bool emptyCalldata) public {
        // keep domain wide
        // Deploy a helper that distinguishes between call with msg.value==0 and the calldata form
        Helper h = new Helper();

        // build calldata: either empty or some payload starting with firstByte
        bytes memory data;
        if (emptyCalldata) {
            data = "";
        } else {
            data = abi.encodePacked(firstByte, bytes("rest"));
        }

        // Try calling forward and observe whether it reverted or not
        bool ok;
        try c.forward(address(h), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): The reference implementation (which uses callee.call(_data))
        // never treats a zero-value calldata call as if ETH were sent; thus when calldata is empty and the
        // callee's receive() exists and is payable, the reference's call(...) invokes fallback/receive the same
        // as call{value:0}(...). The mutant can differ and cause a revert for some inputs. We assert that
        // the reference (this deployed c) does not revert when the helper contract is designed so that
        // only a calldata-only call should succeed: helper.succeedsOnCalldataOnly returns true means the
        // correct contract will succeed. The helper below is constructed so that for empty calldata it will
        // succeed under the reference policy; therefore ok must be true for the reference C for all inputs.
        assertTrue(ok);
    }
}

// Helper that distinguishes behavior: its fallback will revert if msg.data is empty but msg.value==0
// while a non-empty calldata will succeed. This embodies an adversarial callee where using call{value:0}
// could affect which function is picked by some subtle EVM resolution in other contexts. Here it forces
// a difference in observed success between implementations in which the mutant might change semantics.
contract Helper {
    fallback() external payable {
        // If calldata is empty, revert to simulate an adversarial callee that requires non-empty calldata
        // to succeed. For non-empty calldata, accept.
        if (msg.data.length == 0) {
            revert("empty data not allowed");
        }
        // otherwise do nothing (succeed)
    }

    receive() external payable {
        // If Ether is received with empty calldata, revert to simulate a callee that distinguishes
        revert("no ETH receives");
    }
}

