contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: address callee is not enough because fuzzer supplies EOAs with no code
    // so we fuzz a byte selector (bytes1 b) to craft calldata and a bool that toggles whether callee
    // uses receive-path to revert. The adversarial helper is deployed based on the bool.
    function testFuzz_property(bytes1 sel, bool triggerReceive) public {
        // keep domain wide; no tight assumptions
        // Deploy adversarial callee that will revert if it receives ETH in receive(), otherwise handle fallback
        AttackerHelper helper = new AttackerHelper(triggerReceive);

        // craft calldata: put the selector byte followed by some padding
        bytes memory data = abi.encodePacked(sel, bytes3(0));

        // Call forward and capture whether it reverts. The reference C (without {value:0}) should
        // not revert for any inputs because low-level call without value will route to fallback when calldata present.
        bool ok;
        try c.forward(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General assertion: the reference implementation never reverts for any callee+calldata combination
        // in our admissible domain; the mutant (using call{value:0}) can cause a different dispatch
        // selecting receive() and thus can revert for some inputs. Assert that forward did not revert.
        assertTrue(ok);
    }
}

// Adversarial helper: when triggerReceive is true, its fallback will revert but its receive will also revert
// when called with value; when triggerReceive is false, it behaves normally (fallback succeeds).
contract AttackerHelper {
    bool public triggerReceive;
    constructor(bool _t) payable {
        triggerReceive = _t;
    }
    // fallback to accept calldata; we succeed (do nothing) so reference C's call (no value) returns true
    fallback() external payable {
        // succeed silently
    }
    // receive will revert conditionally to emulate a contract that distinguishes receive vs fallback
    receive() external payable {
        if (triggerReceive) {
            revert("receive reverted");
        }
    }
}

