    function run(address callee, bytes calldata data) public {
        // Precondition: the external call should succeed when invoked directly from this contract.
        // We check this by performing the call here; require it succeeds so the test case targets successful downstream calls.
        (bool ok,) = callee.call(data);
        require(ok, "precondition: callee.call must succeed");

