import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary bytes payload sent through forward
    function testFuzz_property(bytes memory payload) public {
        // deploy a helper that always succeeds on low-level calls
        SucceedsReceiver succ = new SucceedsReceiver();

        // ensure succ has some balance so payable fallbacks/receives can be exercised if payload sends value
        vm.deal(address(this), 1 ether);

        // Call c.forward with the helper's address and the fuzzed payload.
        // Use try/catch to capture whether forward returned successfully.
        bool ok;
        try c.forward(address(succ), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any payload and a callee whose low-level call succeeds (SucceedsReceiver),
        // the correct contract C will allow forward to succeed (ok == true). The mutant that
        // inverts the require would make forward revert (ok == false) for such a succeeding callee.
        assertTrue(ok);
    }
}

// Adversarial helper: always succeeds when called via low-level call
contract SucceedsReceiver {
    // Accept any call and do nothing (succeeds)
    fallback() external payable { }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function performing the distinguishing interaction and final assertion
    function run(address callee, bytes calldata data) public {
        // perform the forwarding call; on P this will revert when the low-level call fails,
        // so the assert below is only reached when the inner call succeeded.
        bool ok;
        // We make the low-level call and capture whether the external call would succeed
        // by calling the callee directly from this test contract using .call. This lets us
        // compute what the forward should require. However we must only observe c via its
        // public surface, so we instead perform the single state-changing interaction on c:
        // call c.forward which on P reverts when the callee.call fails, preventing reaching
        // the final assert. On M it continues even if callee.call failed, so we can detect
        // that by checking whether the callee.call would have returned false.

        // To obtain the would-be success value of callee.call without changing c, we perform
        // a static (non-state-changing) call from this contract to the target callee using
        // .call — this is allowed and does not modify c.
        (ok,) = callee.call(data);

        // Now invoke the contract under test. On the original P this will revert if ok==false,
        // so the following assert will only be reached when ok==true. On mutant M the call
        // does not revert even if ok==false, so the assert can fail there.
        c.forward(callee, data);

        // The distinguishing property: the forwarded call must have succeeded.
        assert(ok == true);
    }

    // allow receiving Ether if needed by callee
    receive() external payable {}
}

